import requests

BASE = "https://api.example.com/v1"


def get_status():
    return requests.get(BASE + "/status", timeout=10)


def get_report(token):
    return requests.get(BASE + "/report", headers={"Authorization": token}, verify=False, timeout=10)


def fetch_preview(url):
    return requests.get(url, timeout=10).text
